using Microsoft.EntityFrameworkCore;
using Npgsql.EntityFrameworkCore.PostgreSQL.Infrastructure;

namespace CounterpartyRisk.Infrastructure.Persistence;

/// <summary>
/// Owner of the database migrations (#11). It maps no entity: the schema is written as reviewable
/// SQL (partitioning, RLS, grants and CHECK constraints cannot be generated by EF Core), and each
/// module DbContext maps its own schema with <c>ExcludeFromMigrations()</c> (ADR-001 rule 7).
/// Used only by the migration bundle, with the <c>cr_migrator</c> identity; hosts never migrate.
/// </summary>
public sealed class CounterpartyRiskDbContext : DbContext
{
    /// <summary>The history table lives in <c>meta</c>: <c>public</c> is locked down by db/roles.sql.</summary>
    public const string HistorySchema = "meta";

    public const string HistoryTable = "ef_migrations_history";

    public CounterpartyRiskDbContext(DbContextOptions<CounterpartyRiskDbContext> options)
        : base(options)
    {
    }

    /// <summary>Npgsql settings shared by every place that builds this context.</summary>
    public static void ConfigureNpgsql(NpgsqlDbContextOptionsBuilder npgsql)
    {
        ArgumentNullException.ThrowIfNull(npgsql);
        npgsql.MigrationsHistoryTable(HistoryTable, HistorySchema);
    }

    /// <summary>Builds the context for a migration run with the <c>cr_migrator</c> connection.</summary>
    public static CounterpartyRiskDbContext ForMigrations(string migratorConnectionString)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(migratorConnectionString);

        var options = new DbContextOptionsBuilder<CounterpartyRiskDbContext>()
            .UseNpgsql(migratorConnectionString, ConfigureNpgsql)
            .Options;

        return new CounterpartyRiskDbContext(options);
    }
}
